const EMAILJS_ENDPOINT = 'https://api.emailjs.com/api/v1.0/email/send';
const EMAIL_TIMEOUT_MS = 10000;

const withTimeout = (promise) => Promise.race([
  promise,
  new Promise((_, reject) => {
    setTimeout(() => reject(new Error('Email request timed out')), EMAIL_TIMEOUT_MS);
  })
]);

const getEmailConfig = () => ({
  serviceId: process.env.REACT_APP_EMAILJS_SERVICE_ID,
  templateId: process.env.REACT_APP_EMAILJS_TEMPLATE_ID,
  publicKey: process.env.REACT_APP_EMAILJS_PUBLIC_KEY,
});

const formatSubmission = (formData) => {
  const excludedFields = new Set([
    'resumeFileNameFile',
    'portfolioFileNameFile',
    'resumeFileNamePreview',
    'portfolioFileNamePreview',
  ]);

  return Object.entries(formData)
    .filter(([fieldName, value]) => !excludedFields.has(fieldName) && value)
    .map(([fieldName, value]) => `${fieldName}: ${value}`)
    .join('\n');
};

export const sendSubmissionEmail = async (formData) => {
  const { serviceId, templateId, publicKey } = getEmailConfig();

  if (!serviceId || !templateId || !publicKey || !formData.email) {
    return { sent: false, configured: false };
  }

  try {
    await withTimeout(fetch(EMAILJS_ENDPOINT, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        service_id: serviceId,
        template_id: templateId,
        user_id: publicKey,
        template_params: {
          to_email: formData.email,
          applicant_name: `${formData.firstName || ''} ${formData.lastName || ''}`.trim(),
          form_responses: formatSubmission(formData),
        },
      }),
    }).then(async (response) => {
      if (!response.ok) {
        throw new Error(`Email service returned ${response.status}`);
      }
    }));

    return { sent: true, configured: true };
  } catch (error) {
    console.error('Submission email failed:', error);
    return { sent: false, configured: true };
  }
};
